('AGY-002','Agency gross margin','Revenue left after the whole team''s payroll and freelancer and vendor bills.','agency_finance','["digital_marketing"]','{"op":"percent","left":{"op":"subtract","left":{"op":"subtract","left":{"op":"measure","key":"revenue"},"right":{"op":"measure","key":"payroll_cost"}},"right":{"op":"measure","key":"vendor_cost"}},"right":{"op":"measure","key":"revenue"}}','pct(revenue - payroll_cost - vendor_cost, revenue)','%','higher','["revenue","payroll_cost","vendor_cost"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','top'),
('AGY-008','Revenue concentration','The biggest client''s share of revenue. Lower means less dependence on one client.','agency_finance','["digital_marketing"]','{"op":"percent","left":{"op":"measure","key":"largest_client_revenue"},"right":{"op":"measure","key":"revenue"}}','pct(largest_client_revenue, revenue)','%','lower','["largest_client_revenue","revenue"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','top'),
('AGY-009','Net revenue','Fees invoiced in the period (retainer and project), excluding GST.','agency_finance','["digital_marketing"]','{"op":"measure","key":"revenue"}','revenue','currency','higher','["revenue"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-013','Client gross margin','Client revenue left after the team''s hours on the client (at cost) and the client''s freelancer and vendor bills.','agency_finance','["digital_marketing"]','{"op":"percent","left":{"op":"subtract","left":{"op":"subtract","left":{"op":"measure","key":"revenue"},"right":{"op":"measure","key":"delivery_team_cost"}},"right":{"op":"measure","key":"vendor_cost"}},"right":{"op":"measure","key":"revenue"}}','pct(revenue - delivery_team_cost - vendor_cost, revenue)','%','higher','["revenue","delivery_team_cost","vendor_cost"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-034','Freelancer and vendor cost ratio','Freelancer and vendor bills as a share of revenue.','agency_finance','["digital_marketing"]','{"op":"percent","left":{"op":"measure","key":"vendor_cost"},"right":{"op":"measure","key":"revenue"}}','pct(vendor_cost, revenue)','%','lower','["vendor_cost","revenue"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-003','Active clients','Clients with a live retainer or open project on the last day of the period.','agency_clients','["digital_marketing"]','{"op":"measure","key":"active_clients"}','active_clients','count','higher','["active_clients"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','top'),
('AGY-010','Client retention','Clients active at the start of the period who are still active at the end.','agency_clients','["digital_marketing"]','{"op":"percent","left":{"op":"measure","key":"clients_retained"},"right":{"op":"measure","key":"clients_at_start"}}','pct(clients_retained, clients_at_start)','%','higher','["clients_retained","clients_at_start"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-011','Net revenue retention','This period''s revenue from existing clients against the same clients'' revenue last period.','agency_clients','["digital_marketing"]','{"op":"percent","left":{"op":"measure","key":"existing_client_revenue"},"right":{"op":"measure","key":"existing_client_prior_revenue"}}','pct(existing_client_revenue, existing_client_prior_revenue)','%','higher','["existing_client_revenue","existing_client_prior_revenue"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-012','Upsell and cross-sell revenue','Monthly fee added from new services or bigger scope sold to existing clients.','agency_clients','["digital_marketing"]','{"op":"measure","key":"upsell_revenue"}','upsell_revenue','currency','higher','["upsell_revenue"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','top'),
('AGY-014','Retainers at risk','Retainers with notice given, an unconfirmed renewal due within 30 days, or an overdue advance.','agency_clients','["digital_marketing"]','{"op":"measure","key":"retainers_at_risk"}','retainers_at_risk','count','lower','["retainers_at_risk"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-004','New clients onboarded','Clients whose first invoice falls in the period.','agency_growth','["digital_marketing"]','{"op":"measure","key":"new_customers"}','new_customers','count','higher','["new_customers"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','top'),
('AGY-005','Pipeline coverage','Weighted value of open prospects against the revenue still to book this month.','agency_growth','["digital_marketing"]','{"op":"divide","left":{"op":"measure","key":"weighted_pipeline"},"right":{"op":"measure","key":"revenue_to_book"}}','weighted_pipeline / revenue_to_book','1','higher','["weighted_pipeline","revenue_to_book"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','top'),
('AGY-006','Proposal win rate','Proposals won as a share of proposals decided (won or lost) in the period.','agency_growth','["digital_marketing"]','{"op":"percent","left":{"op":"measure","key":"deals_won"},"right":{"op":"add","left":{"op":"measure","key":"deals_won"},"right":{"op":"measure","key":"deals_lost"}}}','pct(deals_won, deals_won + deals_lost)','%','higher','["deals_won","deals_lost"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','top'),
('AGY-007','New leads','New enquiries logged in the pipeline (website, social, referral).','agency_growth','["digital_marketing"]','{"op":"measure","key":"leads_generated"}','leads_generated','count','higher','["leads_generated"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','top'),
('AGY-020','On-time delivery','Deliverables first submitted on or before the due date, out of those due in the period.','agency_delivery','["digital_marketing"]','{"op":"percent","left":{"op":"measure","key":"deliverables_on_time"},"right":{"op":"measure","key":"deliverables_due"}}','pct(deliverables_on_time, deliverables_due)','%','higher','["deliverables_on_time","deliverables_due"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-021','Retainer fulfilment','Deliverables approved against those scoped in the retainer for the period.','agency_delivery','["digital_marketing"]','{"op":"percent","left":{"op":"measure","key":"deliverables_approved"},"right":{"op":"measure","key":"deliverables_scoped"}}','pct(deliverables_approved, deliverables_scoped)','%','higher','["deliverables_approved","deliverables_scoped"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-030','Average turnaround time','Average working days from brief received to first submission.','agency_delivery','["digital_marketing"]','{"op":"divide","left":{"op":"measure","key":"turnaround_days"},"right":{"op":"measure","key":"deliverables_submitted"}}','turnaround_days / deliverables_submitted','days/count','lower','["turnaround_days","deliverables_submitted"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-022','First-time approval rate','Deliverables approved with no revision rounds, out of those approved.','agency_quality','["digital_marketing"]','{"op":"percent","left":{"op":"measure","key":"first_time_approvals"},"right":{"op":"measure","key":"deliverables_approved"}}','pct(first_time_approvals, deliverables_approved)','%','higher','["first_time_approvals","deliverables_approved"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-023','Average revision rounds','Revision rounds per approved deliverable.','agency_quality','["digital_marketing"]','{"op":"divide","left":{"op":"measure","key":"revision_rounds"},"right":{"op":"measure","key":"deliverables_approved"}}','revision_rounds / deliverables_approved','rounds/count','lower','["revision_rounds","deliverables_approved"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-024','Client goal attainment','Clients that met their agreed monthly goal, out of clients with a goal.','agency_quality','["digital_marketing"]','{"op":"percent","left":{"op":"measure","key":"clients_goal_met"},"right":{"op":"measure","key":"clients_with_goal"}}','pct(clients_goal_met, clients_with_goal)','%','higher','["clients_goal_met","clients_with_goal"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-025','Client satisfaction','Average 1 to 5 rating from each client''s main contact.','agency_quality','["digital_marketing"]','{"op":"divide","left":{"op":"measure","key":"csat_points"},"right":{"op":"measure","key":"csat_responses"}}','csat_points / csat_responses','points/count','higher','["csat_points","csat_responses"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-031','Client onboarding time','Average working days from contract signed to first deliverable approved.','agency_operations','["digital_marketing"]','{"op":"divide","left":{"op":"measure","key":"onboarding_days"},"right":{"op":"measure","key":"clients_onboarded"}}','onboarding_days / clients_onboarded','days/count','lower','["onboarding_days","clients_onboarded"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-032','Team utilisation','Hours logged to client work as a share of the delivery team''s available hours.','agency_operations','["digital_marketing"]','{"op":"percent","left":{"op":"measure","key":"client_hours"},"right":{"op":"measure","key":"available_hours"}}','pct(client_hours, available_hours)','%','higher','["client_hours","available_hours"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','top'),
('AGY-033','Over-servicing','Hours spent on retainers beyond the hours scoped, as a share of the hours scoped.','agency_operations','["digital_marketing"]','{"op":"percent","left":{"op":"subtract","left":{"op":"measure","key":"retainer_hours"},"right":{"op":"measure","key":"scoped_hours"}},"right":{"op":"measure","key":"scoped_hours"}}','pct(retainer_hours - scoped_hours, scoped_hours)','%','lower','["retainer_hours","scoped_hours"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-035','Advance collected on time','Retainer invoices paid by their due date, out of those raised.','agency_operations','["digital_marketing"]','{"op":"percent","left":{"op":"measure","key":"retainer_invoices_on_time"},"right":{"op":"measure","key":"retainer_invoices"}}','pct(retainer_invoices_on_time, retainer_invoices)','%','higher','["retainer_invoices_on_time","retainer_invoices"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-050','Reach','Accounts reached across the client''s channels.','agency_client_results','["digital_marketing"]','{"op":"measure","key":"social_reach"}','social_reach','count','higher','["social_reach"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-051','Engagement rate','Likes, comments, shares and saves as a share of reach.','agency_client_results','["digital_marketing"]','{"op":"percent","left":{"op":"measure","key":"social_engagements"},"right":{"op":"measure","key":"social_reach"}}','pct(social_engagements, social_reach)','%','higher','["social_engagements","social_reach"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-052','Views','Video and reel views across the client''s channels.','agency_client_results','["digital_marketing"]','{"op":"measure","key":"video_views"}','video_views','count','higher','["video_views"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-053','Follower growth','Change in followers over the period, against followers at the start.','agency_client_results','["digital_marketing"]','{"op":"percent","left":{"op":"subtract","left":{"op":"measure","key":"followers"},"right":{"op":"measure","key":"followers_start"}},"right":{"op":"measure","key":"followers_start"}}','pct(followers - followers_start, followers_start)','%','higher','["followers","followers_start"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all'),
('AGY-054','Cost per lead','Paid advertising spend for each lead from paid campaigns.','agency_client_results','["digital_marketing"]','{"op":"divide","left":{"op":"measure","key":"advertising_spend"},"right":{"op":"measure","key":"paid_leads"}}','advertising_spend / paid_leads','currency/count','lower','["advertising_spend","paid_leads"]',false,'["https://agencyanalytics.com/blog/agency-metrics-kpis-profitability-growth","https://www.netsuite.com/portal/resource/articles/erp/marketing-agency-kpis.shtml","https://whatagraph.com/blog/articles/agency-metrics-kpis","https://predictableprofits.com/10-kpis-for-agency-success/"]','all')
